head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getColumnEditPlaceholderChar]<br/>Body Column 정보를 사용하여 특정 Column 의 editPlaceholderChar 속성값을 반환합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 editPlaceholderChar 속성값을 조회할 Body Column 의 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "Body Column 이 inputType='text' 또는 'calendar' 인 경우에 유효한 값을 반환합니다.",
        "파라미터에 해당하는 Body Column 의 editPlaceholderChar 속성값을 반환해야 합니다.",
        "Body Column 의 inputType 속성값이 'text' 또는 'calendar' 가 아니면 false 를 반환해야 합니다.",
        "파라미터가 유효하지 않으면 false 를 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Column 인덱스 - 0:txtChar(text, editPlaceholderChar=_) / 1:calChar(calendar, editPlaceholderChar=_) / 2:txtNone(text, editPlaceholderChar 미설정) / 3:numCol(number, 비-text/calendar) / 4:txtHide(text, editPlaceholderChar=_, 숨김 setColumnVisible(4,false)). 숨김 Column 도 포함하여 인덱스가 부여됨. 데이터 Row 4개.\n[절차] columnInfo(인덱스) 선택 후 (getColumnEditPlaceholderChar 실행) 클릭.\n[확인] 0=editPlaceholderChar 문자열 / 1=calendar 유효값 / 2=미설정 실측값 / 3=false(비-text/calendar) / 4=숨김 text 값 / 99=false(유효하지않음) 가 반환영역에 출력됨."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="txtChar" name="txtChar" dataType="text"></w2:column>';
    strDlt += '<w2:column id="calChar" name="calChar" dataType="text"></w2:column>';
    strDlt += '<w2:column id="txtNone" name="txtNone" dataType="text"></w2:column>';
    strDlt += '<w2:column id="numCol" name="numCol" dataType="text"></w2:column>';
    strDlt += '<w2:column id="txtHide" name="txtHide" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "txtChar": "20260101", "calChar": "20260201", "txtNone": "노트북", "numCol": "100", "txtHide": "20260301" },
        { "txtChar": "20260102", "calChar": "20260202", "txtNone": "모니터", "numCol": "200", "txtHide": "20260302" },
        { "txtChar": "20260103", "calChar": "20260203", "txtNone": "키보드", "numCol": "300", "txtHide": "20260303" },
        { "txtChar": "20260104", "calChar": "20260204", "txtNone": "마우스", "numCol": "400", "txtHide": "20260304" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 5컬럼 + gBody) - Header inputType 은 text, gBody 가 실제 inputType
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:720px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getColumnEditPlaceholderChar 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol1" value="일자(text char 설정)"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol2" value="일자(calendar char 설정)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol3" value="품목(text char 미설정)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol4" value="수량(number)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol5" value="일자(text 숨김)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // index 0 : txtChar (text, editPlaceholderChar 설정)
    strTarget += '<w2:column width="140" style="" inputType="text" editFormat="####/##/##" editPlaceholderChar="_" id="txtChar" dataList="txtChar"></w2:column>';
    // index 1 : calChar (calendar, editPlaceholderChar 설정) - calendar 도 유효 입증
    strTarget += '<w2:column width="140" style="" inputType="calendar" calendarValueType="yearMonthDate" displayFormat="yyyy/MM/dd" editFormat="####/##/##" editPlaceholderChar="_" id="calChar" dataList="calChar"></w2:column>';
    // index 2 : txtNone (text, editPlaceholderChar 미설정)
    strTarget += '<w2:column width="120" style="" inputType="text" id="txtNone" dataList="txtNone"></w2:column>';
    // index 3 : numCol (number, 비-text/calendar) -> false
    strTarget += '<w2:column width="100" style="" inputType="number" id="numCol" dataList="numCol"></w2:column>';
    // index 4 : txtHide (text, editPlaceholderChar 설정) - setColumnVisible(4,false) 로 숨김 -> 숨김 포함 인덱스 검증용
    strTarget += '<w2:column width="*" style="" inputType="text" editFormat="####/##/##" editPlaceholderChar="_" id="txtHide" dataList="txtHide"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 다섯번째 Column(txtHide, 인덱스 4) 숨김 -> 숨김 Column 포함 인덱스 검증용
    target1.setColumnVisible(4, false);
}



// getColumnEditPlaceholderChar 조회 (메인 검증)
scwin.btn_getColumnEditPlaceholderChar_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());

    // getColumnEditPlaceholderChar : text/calendar Column 의 editPlaceholderChar 속성값 반환
    // (text/calendar 아님 / 유효하지 않은 파라미터 는 모두 false)
    let result = target1.getColumnEditPlaceholderChar(columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue("getColumnEditPlaceholderChar(" + columnInfo + ") -> 반환값: " + result);
}
